package com.pp.shaderlod.optimization.sildurworld;
import java.util.*;import java.nio.file.*;import net.irisshaders.iris.Iris;import net.irisshaders.iris.targets.RenderTargets;import org.lwjgl.opengl.*;import com.pp.shaderlod.optimization.*;import com.pp.shaderlod.optimization.photon.*;import com.pp.shaderlod.optimization.sildurpixel.*;import com.pp.shaderlod.optimization.sildurpixel.mixin.*;import com.pp.shaderlod.optimization.sildurspatial.SildurSpatialGl;
/** Original RGB producer return→native consumer, no history/geometry/nativeAA remap. */
public final class SildurWorldRuntime{
 private static final PhotonSpatialEpoch EPOCH=new PhotonSpatialEpoch();private static Object pipeline,pack,core,renderer;private static RenderTargets targets;private static Map<String,String> profile=Map.of();private static SildurPixelPassView producer,consumer;private static PhotonSpatialEpoch.Context context;private static SildurWorldGl.Proof started,completed;private static boolean active;private static long returns,consumers,fallbacks,diagnosticGeneration=Long.MIN_VALUE;private static String first="not consumed",last="native";
 private static final com.pp.shaderlod.optimization.sourcecache.EarlyAlphaSourceCache SOURCE_CACHE=new com.pp.shaderlod.optimization.sourcecache.EarlyAlphaSourceCache();
 private static long sourceGeneration,sourceLookups,sourceProofReplays;
 private SildurWorldRuntime(){}public static String status(){return "ordinary nativeRGB0.85 returnedProducerDraws="+returns+" readyConsumerDraws="+consumers+" (not eligible pixels) fallback="+fallbacks+" first="+first+" last="+last+" sourceLookups="+sourceLookups+" sourceProofReplays="+sourceProofReplays;}
 private static Map<String,String> options(){var p=Iris.getCurrentPack().orElse(null);if(p==null)return Map.of();var o=p.getShaderPackOptions();return SildurPixelOptionGuard.snapshot(o.getOptionSet(),o.getOptionValues(),true);}
 private static boolean requested(){var c=OptimizationRuntimeContext.core();return c!=null&&c.settings().enabled()&&c.preset()!=com.pp.shaderlod.LodPreset.QUALITY&&c.optimizations().enabled(OptimizationId.PIXEL_SCALE)&&OptimizationConfig.requested(OptimizationId.PIXEL_SCALE)&&!com.pp.shaderlod.integration.makeupquad.MakeUpQuadLifecycle.suspended();}
 public static void invalidate(){SOURCE_CACHE.invalidate();sourceGeneration++;resetFrame();}
 private static void resetFrame(){EPOCH.revoke();pipeline=pack=core=null;targets=null;producer=consumer=null;context=null;started=completed=null;active=false;}
 private static void lose(String why){SOURCE_CACHE.invalidate();if(first.equals("not consumed"))first=why;last=why;active=false;EPOCH.revoke();started=completed=null;context=null;SildurPixelRuntime.worldRefused(why);}
 public static void begin(Object p,RenderTargets t,Object deferred){resetFrame();pipeline=p;renderer=deferred;targets=t;pack=Iris.getCurrentPack().orElse(null);core=OptimizationRuntimeContext.core();if(!requested()){last="native world; PIXEL request inactive or Quality";return;}if(diagnosticGeneration!=OptimizationConfig.generation()){diagnosticGeneration=OptimizationConfig.generation();first="not consumed";}profile=Map.copyOf(options());if(!SildurWorldContract.graph(profile)){last="native world; AO/spatial/query coexistence outside current slice";return;}if(!requested())return;try{var e=SildurPixelEnvironment.actual();if(!SildurWorldContract.options(profile)||!e.overworld()||!e.clear()||!e.projection()||Iris.isFallback()||!Iris.getShaderPackOptionQueue().isEmpty()||!com.pp.shaderlod.optimization.sildurao.SildurAoApiPins.exact())return;var client=net.minecraft.client.Minecraft.getInstance();var mods=com.pp.shaderlod.integration.makeupquad.MakeUpQuadRuntime.loadedStack();if(!com.pp.shaderlod.integration.makeupquad.MakeUpQuadRuntime.stackMatches(mods)||!com.pp.shaderlod.integration.makeupquad.MakeUpQuadRuntime.resourcesMatch(client.getResourcePackRepository().getSelectedIds())||!com.mojang.blaze3d.systems.RenderSystem.isOnRenderThread()||net.irisshaders.iris.shadows.ShadowRenderingState.areShadowsCurrentlyBeingRendered())return;var platform=net.irisshaders.iris.platform.IrisPlatformHelpers.getInstance();if(platform.isModLoaded("distanthorizons")||platform.isModLoaded("voxy"))return;String name=Iris.getIrisConfig().getShaderPackName().orElse(null);if(name==null||!Path.of(name).getFileName().toString().equals(name))return;Path file=Iris.getShaderpacksDirectory().resolve(name);if(!source(file,profile))return;
 active=true;last="qualified native snapshot; awaiting deferred graph roles";
 }catch(RuntimeException|LinkageError failed){lose("native RGB graph/API unavailable "+failed.getClass().getSimpleName());}}
 public static void beginComposite(Object owner,RenderTargets t,List<?> passes){if(owner!=renderer||t!=targets||!active)return;try{ for(Object row:passes){var pass=(SildurPixelPassView)row;if(pass.shaderlod$name().equals("deferred"))producer=pass;if(pass.shaderlod$name().equals("deferred1"))consumer=pass;}if(producer==null||consumer==null||!Arrays.equals(producer.shaderlod$drawBuffers(),new int[]{14})||!Arrays.equals(consumer.shaderlod$drawBuffers(),new int[]{4,6})||producer.shaderlod$scale().scale()!=.85f||consumer.shaderlod$scale().scale()!=1f||!producer.shaderlod$mips().isEmpty()||producer.shaderlod$scale().viewportX()!=0||producer.shaderlod$scale().viewportY()!=0||consumer.shaderlod$scale().viewportX()!=0||consumer.shaderlod$scale().viewportY()!=0){lose("native RGB graph roles unavailable");return;}var settings=((com.pp.shaderlod.optimization.sildurao.mixin.SildurAoTargetsView)t).shaderlod$settings().get(14);if(settings==null||!settings.shouldClear()||settings.getClearColor().isEmpty()||!settings.getClearColor().get().equals(0,0,0,-1)){lose("nativeRGB field clear/negative marker unavailable");return;}active=true;last="qualified graph; awaiting original nativeRGB producer";}catch(RuntimeException|LinkageError failed){lose("native deferred role API unavailable");}}
 private static boolean source(Path file,Map<String,String> actual){
  sourceLookups++;
  try{
   var current=Iris.getCurrentPack().orElse(null);if(current==null){SOURCE_CACHE.invalidate();return false;}
   var o=current.getShaderPackOptions();var c=net.minecraft.client.Minecraft.getInstance();
   boolean accepted=SOURCE_CACHE.check(SildurWorldRuntime.class,Iris.getShaderpacksDirectory(),file.getFileName().toString(),SildurPixelContract.ID,actual,
    current,o.getOptionValues(),o.getOptionSet(),Iris.getPipelineManager().getPipelineNullable(),c.level,sourceGeneration,
    Arrays.asList(OptimizationRuntimeContext.core(),Map.copyOf(Iris.getShaderPackOptionQueue()),List.copyOf(c.getResourcePackRepository().getSelectedIds())),
    c.getResourceManager().listPacks().map(net.minecraft.server.packs.PackResources::packId).toList(),
    ()->{sourceProofReplays++;return SildurPixelSourceProof.verify(file,actual,()->SildurWorldRuntime.class.getResourceAsStream("/assets/shaderlod/adapters/patches/adapters/sildurs-vibrant-shaders.json"));});
   if(!accepted)SOURCE_CACHE.invalidate();return accepted;
  }catch(Exception|LinkageError failed){SOURCE_CACHE.invalidate();return false;}
  catch(Error failure){SOURCE_CACHE.invalidate();throw failure;}
 }
 private static boolean current(){return active&&requested()&&pack==Iris.getCurrentPack().orElse(null)&&core.equals(OptimizationRuntimeContext.core())&&profile.equals(options())&&Iris.getPipelineManager().getPipelineNullable()==pipeline&&Iris.getShaderPackOptionQueue().isEmpty();}
 private static PhotonSpatialEpoch.Context now(int frame){return new PhotonSpatialEpoch.Context(pipeline,pack,targets,OptimizationConfig.generation(),frame,targets.getCurrentWidth(),targets.getCurrentHeight(),producer.shaderlod$program().getProgramId(),consumer.shaderlod$program().getProgramId(),profile);}
 public static void beforeDraw(){if(!active||producer==null||consumer==null)return;int p=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(p<=0||GL20.glGetUniformLocation(p,"shaderlodSildurWorldReady")<0)return;SildurWorldGl.ready(p,false,0,0);started=null;try{if(!current()||producer==null||consumer==null){fallbacks++;return;}int frame=SildurSpatialGl.integer(p,"frameCounter");if(frame<0||frame>=16777216){lose("native frame epoch unavailable");return;}if(p==producer.shaderlod$program().getProgramId()){var proof=SildurWorldGl.producer(targets,p);if(!proof.valid()){lose(proof.reason());return;}context=now(frame);EPOCH.begin(context);started=proof;SildurWorldGl.ready(p,true,context.width(),context.height());}else if(p==consumer.shaderlod$program().getProgramId()){var proof=SildurWorldGl.consumer(targets,p);boolean valid=completed!=null&&context!=null&&proof.valid()&&Objects.equals(completed.inputs(),proof.inputs())&&SildurSpatialGl.sameControls(completed.controls(),proof.controls())&&EPOCH.consumer(now(frame),proof.output().cache(),proof.output().sky());if(valid){SildurWorldGl.ready(p,true,context.width(),context.height());consumers++;last="completed current nativeRGB consumer";}else{fallbacks++;lose("current nativeRGB field unavailable: "+proof.reason());}}}catch(RuntimeException|LinkageError failed){lose("native RGB draw proof unavailable "+failed.getClass().getSimpleName());}}
 public static void afterDraw(){if(started==null||context==null||producer==null)return;try{int p=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);var proof=SildurWorldGl.producer(targets,p);boolean valid=p==context.producer()&&current()&&proof.valid()&&Objects.equals(started,proof);EPOCH.returned(now(SildurSpatialGl.integer(p,"frameCounter")),proof.output(),true,valid);if(valid){completed=proof;returns++;}else lose("nativeRGB producer changed before original return");}catch(RuntimeException|LinkageError failed){lose("nativeRGB original return unavailable");}finally{started=null;}}
 public static void abort(){if(active)lose("nativeRGB original draw did not return");}
 public static void restore(){if(producer==null&&consumer==null)return;int p=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(p>0&&GL20.glGetUniformLocation(p,"shaderlodSildurWorldReady")>=0)SildurWorldGl.ready(p,false,0,0);}

 public static void qualifyLoadedSource(net.irisshaders.iris.shaderpack.ShaderPack pack){String name=Iris.getIrisConfig().getShaderPackName().orElse(null);if(name!=null)source(Iris.getShaderpacksDirectory().resolve(name),options());}
}
